<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { readFeature, writeFeature, featureError, type Page, type Refund } from '@/services/additionalFeatures'
import { money } from '@/services/operationsApi'
import OpsPager from './OpsPager.vue'
import './operations.css'
interface Purchase { id:number;userId:string;courseId:number;amount:number;createdAt:string;renewal:boolean }
const purchases=ref<Page<Purchase>>({content:[],number:0,totalElements:0,totalPages:0}),rows=ref<Page<Refund>>({content:[],number:0,totalElements:0,totalPages:0}),userId=ref(''),reason=ref(''),note=ref(''),selected=ref<Purchase>(),revokeAccess=ref(false),busy=ref(false),error=ref(''),message=ref('')
const base='/api/nihongo-user/admin/refunds'
async function loadPurchases(page=0){purchases.value=await readFeature(`${base}/purchases`,{page,userId:userId.value||undefined})}
async function load(page=0){rows.value=await readFeature(base,{page})}
async function action(work:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';message.value='';try{await work()}catch(cause){error.value=featureError(cause)}finally{busy.value=false}}
const request=()=>action(async()=>{if(!selected.value)return;await writeFeature(base,{purchaseId:selected.value.id,reason:reason.value,revokeAccess:revokeAccess.value});await load();selected.value=undefined;reason.value='';message.value='Đã tạo yêu cầu; cần duyệt để tiền được hoàn về ví.'})
const review=(row:Refund,approve:boolean)=>action(async()=>{if(note.value.trim().length<10){error.value='Nhập ghi chú duyệt tối thiểu 10 ký tự.';return}if(!confirm(`${approve?'Hoàn '+money(row.amount)+' về ví':'Từ chối'} yêu cầu ${row.id}? ${row.revokeAccess?'Quyền học khóa cũng sẽ được thu hồi.':''}`))return;await writeFeature(`${base}/${row.id}/review`,{approve,note:note.value,version:row.version});await load(rows.value.number);message.value='Đã xử lý yêu cầu.'})
onMounted(()=>action(async()=>{await Promise.all([load(),loadPurchases()])}))
</script>
<template><div class="ops-page"><h1>Hoàn tiền khóa học</h1><p>Hoàn toàn bộ số tiền thực trả sau khuyến mãi về ví; không chuyển tiền ngân hàng. Tạo yêu cầu và duyệt là hai bước riêng.</p><p v-if="error" class="ops-error" role="alert">{{ error }}</p><p v-if="message" class="ops-success" role="status">{{ message }}</p><section class="ops-panel"><h2>Chọn giao dịch</h2><form class="ops-actions" @submit.prevent="action(()=>loadPurchases())"><input v-model="userId" placeholder="Lọc UUID học viên (tùy chọn)" maxlength="36"><button class="ops-button secondary" :disabled="busy">Tìm</button></form><div class="ops-table-wrap"><table class="ops-table"><thead><tr><th>Mã</th><th>Học viên</th><th>Khóa</th><th>Đã trả</th><th></th></tr></thead><tbody><tr v-for="row in purchases.content" :key="row.id"><td>{{ row.id }}</td><td>{{ row.userId }}</td><td>{{ row.courseId }} · {{ row.renewal?'Gia hạn':'Mua mới' }}</td><td>{{ money(row.amount) }}</td><td><button class="ops-button secondary" :disabled="busy||row.amount<=0" @click="selected=row">Chọn</button></td></tr></tbody></table></div><OpsPager :page="purchases.number" :total-pages="purchases.totalPages" :total-elements="purchases.totalElements" :busy="busy" @change="loadPurchases" /></section><form v-if="selected" class="ops-panel ops-form" @submit.prevent="request"><h2 class="wide">Yêu cầu hoàn giao dịch {{ selected.id }} · {{ money(selected.amount) }}</h2><label class="wide">Lý do<textarea v-model="reason" minlength="10" maxlength="500" required></textarea></label><label class="wide"><input v-model="revokeAccess" type="checkbox"> Thu hồi toàn bộ quyền học khóa này, kể cả thời hạn đã gia hạn</label><button class="ops-button" :disabled="busy">Tạo yêu cầu</button><button class="ops-button secondary" type="button" @click="selected=undefined">Hủy</button></form><section class="ops-panel"><h2>Yêu cầu và lịch sử hoàn tiền</h2><label>Ghi chú duyệt / từ chối<input v-model="note" minlength="10" maxlength="500"></label><div class="ops-table-wrap"><table class="ops-table"><thead><tr><th>Yêu cầu / giao dịch</th><th>Số tiền</th><th>Lý do</th><th>Trạng thái</th><th></th></tr></thead><tbody><tr v-for="row in rows.content" :key="row.id"><td>{{ row.id }} / {{ row.purchaseId }}</td><td>{{ money(row.amount) }}</td><td>{{ row.reason }}<p v-if="row.reviewNote" class="ops-muted">{{ row.reviewNote }}</p></td><td>{{ row.status }}</td><td v-if="row.status==='PENDING'"><button class="ops-button" :disabled="busy||note.trim().length<10" @click="review(row,true)">Duyệt</button> <button class="ops-button secondary" :disabled="busy||note.trim().length<10" @click="review(row,false)">Từ chối</button></td><td v-else>Đã xử lý</td></tr></tbody></table></div><OpsPager :page="rows.number" :total-pages="rows.totalPages" :total-elements="rows.totalElements" :busy="busy" @change="load" /></section></div></template>
